"""Bounded lossless optimizer for character-level prefix reuse."""

from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Choose lossless row-specific column permutations using bounded Trie-aware heuristics."""

    def __init__(self, df: pd.DataFrame = None):
        """Store only input metadata; no input frame is modified."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Convert one scalar to the evaluator's text, mapping scalar missing values to empty."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """Return the exact common-prefix length using binary-search slice comparisons."""
        hi = min(len(a), len(b))
        lo = 0
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Return ideal character-Trie reuse as LCPs of sorted adjacent row strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _global_order(cells, mode: int = 0) -> List[int]:
        """Rank columns globally by length-weighted or length-neutral repeated-value pairs."""
        n, m = cells.shape
        ranked = []
        for c in range(m):
            counts = {}
            total_length = 0
            for value in cells[:, c]:
                counts[value] = counts.get(value, 0) + 1
                total_length += len(value)

            weighted = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            pairs = sum(count * (count - 1) for count in counts.values())

            if mode == 0:
                key = weighted
            elif mode == 1:
                key = pairs * max(1, total_length // max(1, n))
            else:
                key = weighted + pairs

            ranked.append((key, pairs, c))

        ranked.sort(key=lambda item: (-item[0], -item[1], item[2]))
        return [item[2] for item in ranked]

    def _conditional_orders(self, cells) -> List[List[int]]:
        """Build a depth-four conditional prefix tree using cached integer value codes.

        At each node, at most 24 remaining fields are examined.  The selected
        field maximizes length-weighted equal-value pair repetition; rows are
        partitioned by its cached code and each partition receives its own
        recursively selected suffix.  Small or unproductive partitions use a
        deterministic global tail.
        """
        n, m = cells.shape
        if n == 0:
            return []
        if n < 2 or m < 2:
            return [list(range(m)) for _ in range(n)]

        # Factorize each serialized column once.  Codes and lengths are reused
        # by every tree node, avoiding pandas work inside recursion.
        codes = np.empty((n, m), dtype=np.int32)
        lengths = np.empty((n, m), dtype=np.int32)

        for c in range(m):
            mapping = {}
            next_code = 0
            for r in range(n):
                value = cells[r, c]
                code = mapping.get(value)
                if code is None:
                    code = next_code
                    mapping[value] = code
                    next_code += 1
                codes[r, c] = code
                lengths[r, c] = len(value)

        global_tail = self._global_order(cells, 0)
        result = [None] * n
        max_depth = min(4, m - 1)
        max_fields = min(24, m)

        def finish(rows, prefix, remaining):
            """Assign the globally ranked unused suffix to every row in a leaf."""
            tail = [c for c in global_tail if c in remaining]
            order = prefix + tail
            for row in rows:
                result[row] = order[:]

        def visit(rows, remaining, prefix, depth):
            """Select one productive field, partition rows, and recurse with hard bounds."""
            if not rows:
                return
            if not remaining:
                for row in rows:
                    result[row] = prefix[:]
                return
            if len(rows) < 2 or depth >= max_depth:
                finish(rows, prefix, remaining)
                return

            # Candidate fields are already deterministically ranked, so this
            # remains bounded even for very wide frames.
            candidates = [c for c in global_tail if c in remaining][:max_fields]
            best_col = -1
            best_score = 0

            for c in candidates:
                counts = {}
                value_length = {}
                for row in rows:
                    code = int(codes[row, c])
                    counts[code] = counts.get(code, 0) + 1
                    if code not in value_length:
                        value_length[code] = int(lengths[row, c])

                score = sum(
                    value_length[code] * count * (count - 1)
                    for code, count in counts.items()
                    if count > 1
                )

                if score > best_score or (
                    score == best_score and score > 0 and
                    (best_col < 0 or c < best_col)
                ):
                    best_score = score
                    best_col = c

            if best_col < 0 or best_score <= 0:
                finish(rows, prefix, remaining)
                return

            groups = {}
            for row in rows:
                code = int(codes[row, best_col])
                groups.setdefault(code, []).append(row)

            next_remaining = [c for c in remaining if c != best_col]
            next_prefix = prefix + [best_col]

            for group in groups.values():
                if len(group) < 2:
                    finish(group, next_prefix, next_remaining)
                else:
                    visit(group, next_remaining, next_prefix, depth + 1)

        visit(list(range(n)), list(range(m)), [], 0)

        # Defensive completion is only for bounded-recursion safety.
        for r in range(n):
            if result[r] is None:
                result[r] = global_tail[:]
        return result

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize every row according to its supplied source-column permutation."""
        return [
            "".join(cells[r, c] for c in orders[r])
            for r in range(cells.shape[0])
        ]

    def _candidate(self, cells, orders):
        """Materialize one candidate, score it exactly, and sort rows by serialized text."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(range(len(strings)), key=lambda r: (strings[r], r))
        return score, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Return a lossless reordered frame and matching per-row column-name orders."""
        n, m = df.shape
        self.num_rows, self.num_cols = n, m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)
        for r in range(n):
            for c in range(m):
                cells[r, c] = self._cell_text(raw[r, c])

        # Structural constraints are retained conservatively: without a
        # documented encoding, changing their order could violate the caller's
        # contract, so only row sorting is performed in that case.
        constrained = bool(col_merge) or bool(one_way_dep)

        if constrained:
            identity = list(range(m))
            orders = [identity[:] for _ in range(n)]
            strings = self._make_strings(cells, orders)
            row_order = sorted(range(n), key=lambda r: (strings[r], r))
        else:
            global_a = self._global_order(cells, 0)
            global_b = self._global_order(cells, 1)
            tree = self._conditional_orders(cells)

            candidates = (
                [global_a[:] for _ in range(n)],
                [global_b[:] for _ in range(n)],
                tree,
            )

            best = None
            for candidate in candidates:
                score, row_order = self._candidate(cells, candidate)
                signature = tuple(-value for value in candidate[0])
                choice = (score, signature)
                if best is None or choice > best[0]:
                    best = (choice, row_order, candidate)

            _, row_order, orders = best

        out = np.empty((n, m), dtype=object)
        output_orders = []

        for destination, source in enumerate(row_order):
            order = orders[source]
            for j, column in enumerate(order):
                out[destination, j] = raw[source, column]
            output_orders.append([df.columns[column] for column in order])

        result = pd.DataFrame(
            out,
            columns=df.columns,
            index=df.index.take(row_order),
        )
        return result, output_orders

